const sitemapItems = `-- name: SitemapItems :many
SELECT i.id, i.updated_at FROM items i
LEFT JOIN users u ON u.id = i.created_by
WHERE i.status = 'live' AND i.link_status <> 'dead'
  AND (i.via = 'import' OR (i.created_at < now() - interval '7 days' AND i.like_count >= 3
       AND u.trust_level >= 1 AND u.shadow_banned_at IS NULL))
ORDER BY i.score DESC LIMIT 45000
`

type SitemapItemsRow struct {
	ID        int64
	UpdatedAt time.Time
}

func (q *Queries) SitemapItems(ctx context.Context) ([]SitemapItemsRow, error) {
	rows, err := q.db.Query(ctx, sitemapItems)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SitemapItemsRow
	for rows.Next() {
		var i SitemapItemsRow
		if err := rows.Scan(&i.ID, &i.UpdatedAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

